import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_metadata(metadata_str):
    """Remove potentially dangerous characters from metadata fields."""
    # Basic sanitization - strip null bytes and control chars
    cleaned = metadata_str.replace('\x00', '').strip()
    # Limit length to prevent buffer issues
    return cleaned[:256]

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    output_format = request.form.get('format', 'pdf')
    author_meta = request.form.get('author', 'Unknown')
    title_meta = request.form.get('title', '')

    # Generate unique job ID
    job_id = hashlib.sha256(f"{time.time()}{file.filename}".encode()).hexdigest()[:16]

    # Save uploaded file
    safe_name = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{safe_name}")
    file.save(input_path)

    # Determine output path
    output_name = f"{job_id}_output.{output_format}"
    output_path = os.path.join(UPLOAD_DIR, output_name)

    # Sanitize metadata
    author_meta = sanitize_metadata(author_meta)
    title_meta = sanitize_metadata(title_meta)

    # Build conversion command using LibreOffice
    # The --outdir flag specifies output directory
    convert_cmd = f"libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {input_path}"

    # Apply metadata using exiftool post-conversion
    meta_cmd = f'exiftool -Author="{author_meta}" -Title="{title_meta}" {output_path}'

    try:
        # Run conversion
        result = subprocess.run(convert_cmd, shell=True, capture_output=True, 
                              timeout=30, cwd=UPLOAD_DIR)
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()[:200]}), 500

        # Rename LibreOffice output to our expected path
        lo_output = os.path.join(UPLOAD_DIR, f"{job_id}_{os.path.splitext(safe_name)[0]}.{output_format}")
        if os.path.exists(lo_output) and lo_output != output_path:
            os.rename(lo_output, output_path)

        # Apply metadata
        meta_result = subprocess.run(meta_cmd, shell=True, capture_output=True, timeout=10)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        # Cleanup
        for f in [input_path, output_path, f"{output_path}_original"]:
            try:
                os.unlink(f)
            except OSError:
                pass

@app.route('/api/v2/formats', methods=['GET'])
def list_formats():
    return jsonify({'input': list(ALLOWED_EXTENSIONS), 'output': ['pdf', 'docx', 'odt', 'html', 'txt']})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
